INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ein IT-Sicherheitsvorfall immer nur finanzielle Schäden verursacht?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Datenverlust oder Reputationsschäden möglich"}, {"text": "Ja", "correct": false, "because": "Nicht auf Finanzen beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art von Schaden entsteht durch Datenlecks?', 3, '[{"text": "Vertraulichkeitsverlust", "correct": true, "because": "Sensible Daten werden offengelegt"}, {"text": "Hardwarefehler", "correct": false, "because": "Physikalischer Schaden"}, {"text": "Bandbreitenverlust", "correct": false, "because": "Netzwerkproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schadensarten können durch einen Cyberangriff entstehen?', 5, '[{"text": "Finanzielle Verluste", "correct": true, "because": "Durch Erpressung oder Betrug"}, {"text": "Reputationsschäden", "correct": true, "because": "Verlust von Vertrauen"}, {"text": "Softwareoptimierung", "correct": false, "because": "Kein Schaden"}, {"text": "Höhere Bandbreite", "correct": false, "because": "Kein Schadensfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenverlust ist eine Schadensart. b) Erhöhte Sicherheit ist ein Schaden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Sicherheit ist kein Schaden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Bewertung von Schäden in der IT-Sicherheit?', 4, '[{"text": "Datenintegrität", "correct": false, "because": "Wichtig für Vertrauen"}, {"text": "Betriebsunterbrechung", "correct": false, "because": "Verursacht Verluste"}, {"text": "Farbschema", "correct": true, "because": "Kein Schadensfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Reputationsschaden finanziellen Schaden nach sich ziehen kann?', 2, '[{"text": "Ja", "correct": true, "because": "Vertrauensverlust führt zu Umsatzeinbußen"}, {"text": "Nein", "correct": false, "because": "Indirekte Folgen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schadensart entsteht durch Ransomware?', 4, '[{"text": "Datenverfügbarkeit", "correct": true, "because": "Dateien werden gesperrt"}, {"text": "Softwarefehler", "correct": false, "because": "Kein Programmfehler"}, {"text": "Netzwerkausfall", "correct": false, "because": "Anderes Problem"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Schaden immer sofort erkennbar ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Datenlecks oft erst später sichtbar"}, {"text": "Ja", "correct": false, "because": "Verzögerte Erkennung üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein physischer Schaden eine IT-Schadensart?', 2, '[{"text": "Ja", "correct": true, "because": "Z. B. bei Serverausfall"}, {"text": "Nein", "correct": false, "because": "Teil der IT-Infrastruktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schäden können durch Phishing entstehen?', 5, '[{"text": "Identitätsdiebstahl", "correct": true, "because": "Daten werden gestohlen"}, {"text": "Finanzielle Verluste", "correct": true, "because": "Durch Betrug"}, {"text": "Bessere Sicherheit", "correct": false, "because": "Kein Schaden"}, {"text": "Schnellere Netzwerke", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Analyse von Schäden?', 4, '[{"text": "Schadensausmaß", "correct": true, "because": "Bestimmt Dringlichkeit"}, {"text": "Schnelle Lösung", "correct": false, "because": "Analyse vor Lösung"}, {"text": "Design der Warnung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Betriebsunterbrechung ist ein Schaden. b) Sie betrifft nur kleine Firmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, alle Firmen betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Klassifizierung von Schäden?', 3, '[{"text": "Schadensausmaß", "correct": false, "because": "Bestimmt Kategorie"}, {"text": "Ursache", "correct": false, "because": "Hilft bei Analyse"}, {"text": "Firmenlogo", "correct": true, "because": "Kein Schadensfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich rechtliche Schäden erkenne?', 4, '[{"text": "Verstoß gegen Datenschutz prüfen", "correct": true, "because": "Führt zu Bußgeldern"}, {"text": "Nur Hardware prüfen", "correct": false, "because": "Nicht rechtlich"}, {"text": "Farben analysieren", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Schäden nur durch Angriffe entstehen. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Auch durch Fehler oder Ausfälle"}, {"text": "Ja", "correct": false, "because": "Mehrere Ursachen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schadensart ist typisch für DDoS-Angriffe?', 4, '[{"text": "Verfügbarkeitsverlust", "correct": true, "because": "Systeme werden überlastet"}, {"text": "Datenintegrität", "correct": false, "because": "Nicht primär betroffen"}, {"text": "Hardwarefehler", "correct": false, "because": "Kein physischer Schaden"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Schaden mehrere Kategorien betreffen?', 2, '[{"text": "Ja", "correct": true, "because": "Z. B. Datenverlust und Finanzen"}, {"text": "Nein", "correct": false, "because": "Kombinationen üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen minimieren Schäden?', 5, '[{"text": "Backups", "correct": true, "because": "Schützen Datenverfügbarkeit"}, {"text": "Schulungen", "correct": true, "because": "Vermeiden Phishing"}, {"text": "Bunte Interfaces", "correct": false, "because": "Kein Schutz"}, {"text": "Hoher Speicher", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Schadensbewertung unwichtig?', 3, '[{"text": "Auswirkung", "correct": false, "because": "Bestimmt Schwere"}, {"text": "Ursache", "correct": false, "because": "Hilft bei Prävention"}, {"text": "Firmenfarben", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich Schäden analysiere?', 4, '[{"text": "Kategorisieren und Ausmaß bewerten", "correct": true, "because": "Strukturierte Analyse"}, {"text": "Nur Ursache ignorieren", "correct": false, "because": "Wichtig für Lösung"}, {"text": "Zufällig bewerten", "correct": false, "because": "Unsystematisch"}]');
